% Professional Medical Treatment Plan Style
% Provides modern, clean styling for clinical treatment plans

\NeedsTeXFormat{LaTeX2e}
\ProvidesPackage{medical_treatment_plan}[2025/11/05 Medical Treatment Plan Style]

% Required packages
