\pagestyle{fancy}
\fancyhf{}
\fancyhead[L]{\color{primaryblue}\sffamily\small\textbf{Diabetes Treatment Plan}}
\fancyhead[R]{\color{darkgray}\sffamily\small Patient Age: 23}
\fancyfoot[C]{\color{darkgray}\small\thepage}
